DROP TABLE IF EXISTS `colaboradores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `colaboradores` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombres` varchar(100) NOT NULL,
  `apellidos` varchar(100) NOT NULL,
  `tipo_documento` enum('CC','TI','CE','PA','RC','NIT') NOT NULL DEFAULT 'CC',
  `documento` varchar(20) NOT NULL,
  `fecha_nacimiento` date NOT NULL,
  `perfil` enum('Lider Comunitario','Lider Ambiental','Lider Gremial','Lider Social','Lider Empresarial','Influencer','Lider Juvenil','Lider Poblacional','Lider Diferencial','Medios Tradicionales','Amigo','Familia') NOT NULL,
  `nivel_participacion` enum('Simpatizante','Aportante','Activista de Opini├│n','Movilizador','Contradictor') NOT NULL DEFAULT 'Simpatizante',
  `areas_interes` longtext DEFAULT NULL COMMENT 'Array de ├íreas: Educaci├│n, Salud, Medio Ambiente, Econom├¡a, Seguridad, Cultura, Deportes, Tecnolog├¡a, Derechos Humanos, Juventud, Comercio, Plan Centro, Proyectos' CHECK (json_valid(`areas_interes`)),
  `dato_potencial` int(11) DEFAULT 0 COMMENT 'Dato potencial del colaborador',
  `dato_historico` int(11) DEFAULT 0 COMMENT 'Dato hist├│rico del colaborador',
  `estado` enum('Nuevo','Desvinculado','Creci├│','Decrece','Igual') DEFAULT 'Nuevo',
  `observaciones` text DEFAULT NULL,
  `revision` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `lider_directo` varchar(20) DEFAULT NULL COMMENT 'FK: documento del l├¡der',
  `id_curriculum` int(11) DEFAULT NULL,
  `genero` enum('M','F','O') NOT NULL COMMENT 'M=Masculino, F=Femenino, O=Otro',
  `departamento` varchar(50) DEFAULT NULL,
  `municipio` varchar(100) DEFAULT NULL,
  `tipo_territorio` varchar(50) DEFAULT NULL,
  `territorio` varchar(100) DEFAULT NULL,
  `barrio` varchar(255) DEFAULT NULL,
  `direccion` varchar(255) DEFAULT NULL,
  `detalle_ubicacion` varchar(255) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `telefono_whatsapp` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `documento` (`documento`),
  KEY `idx_documento` (`documento`),
  KEY `idx_lider_directo` (`lider_directo`),
  KEY `idx_perfil` (`perfil`),
  KEY `idx_nivel_participacion` (`nivel_participacion`),
  KEY `idx_territorio` (`territorio`),
  KEY `idx_estado` (`estado`),
  KEY `idx_departamento` (`departamento`),
  KEY `idx_email` (`email`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_colaborador_lider_estado` (`lider_directo`,`estado`),
  KEY `idx_colaborador_territorio_perfil` (`territorio`,`perfil`),
  KEY `idx_colaborador_perfil_nivel` (`perfil`,`nivel_participacion`),
  CONSTRAINT `colaboradores_ibfk_1` FOREIGN KEY (`lider_directo`) REFERENCES `colaboradores` (`documento`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
