/*!50003 CREATE*/ /*!50017  /*!50003 TRIGGER trg_colaboradores_after_insert
AFTER INSERT ON colaboradores
FOR EACH ROW
BEGIN
    INSERT INTO logs_auditoria (
        usuario_id,
        accion,
        tabla_afectada,
        registro_id,
        datos_nuevos,
        ip_address,
        user_agent
    ) VALUES (
