        'INSERT',
        'colaboradores',
        NEW.id,
        JSON_OBJECT(
            'id', NEW.id,
            'documento', NEW.documento,
            'nombres', NEW.nombres,
            'apellidos', NEW.apellidos,
            'perfil', NEW.perfil,
            'lider_directo', NEW.lider_directo
        ),
        @current_ip,
        @current_user_agent
    );
END */;;
