DROP TABLE IF EXISTS `curriculum`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `curriculum` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `colaborador_id` int(11) NOT NULL,
  `experiencia_laboral` longtext DEFAULT NULL COMMENT 'Array de {cargo, empresa, fecha_inicio, fecha_fin, descripcion}' CHECK (json_valid(`experiencia_laboral`)),
  `formacion_academica` longtext DEFAULT NULL COMMENT 'Array de {titulo, institucion, fecha_inicio, fecha_fin, nivel}' CHECK (json_valid(`formacion_academica`)),
  `participacion_politica` longtext DEFAULT NULL COMMENT 'Array de {cargo, organizacion, fecha_inicio, fecha_fin, descripcion}' CHECK (json_valid(`participacion_politica`)),
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `resumen_profesional` text DEFAULT NULL,
  `habilidades` text DEFAULT NULL,
  `idiomas` text DEFAULT NULL,
  `reconocimientos` text DEFAULT NULL,
  `referencias` text DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_colaborador_id` (`colaborador_id`),
  CONSTRAINT `curriculum_ibfk_1` FOREIGN KEY (`colaborador_id`) REFERENCES `colaboradores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

